// Find all failed jobs in the emails queue
const failed = await management.api.jobs.find({ queue: 'emails', status: 'failed' });

// Retry each one
for (const job of failed) {
  await management.api.jobs.retry(`${job.queue}:${job.id}`);
}

const stats = await management.api.queues.stats('emails');
console.log(stats);
// { waiting: 12, delayed: 3, processing: 2, completed: 840, failed: 1, total: 858 }

// Subscribe to all terminal events
const off = management.events.job.finished((payload) => {
  console.log(payload.jobId, payload.status);
});

// Subscribe to failures only
management.events.job.failed((payload) => {
  alertTeam(`Job ${payload.jobId} failed: ${payload.error}`);
});

// Unsubscribe later
off();
